#include <bits/stdc++.h>
using namespace std; const int N=100010; int p[N],sz[N];
int find(int x){return p[x]==x?x:p[x]=find(p[x]);}
int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int n,m;cin>>n>>m;for(int i=1;i<=n;i++)p[i]=i,sz[i]=1;while(m--){string op;cin>>op;if(op=="C"){int a,b;cin>>a>>b;int pa=find(a),pb=find(b);if(pa!=pb){p[pa]=pb;sz[pb]+=sz[pa];}}else if(op=="Q1"){int a,b;cin>>a>>b;cout<<(find(a)==find(b)?"Yes":"No")<<'\n';}else{int a;cin>>a;cout<<sz[find(a)]<<'\n';}}return 0;}
